def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= DAILY_SALARY * 0.9:
                    aggressive_bids.append(float(bid))

    if not alive_opponents:
        safe = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            safe = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, safe)))

    slots = max(1, int(supply // WATER_REQ))
    live_count = len(alive_opponents) + 1
    scarcity = live_count - slots
    tight = scarcity >= 2
    medium_tight = scarcity == 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if tight:
        urgency += 2
    elif medium_tight:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        bid = max(DAILY_SALARY * 0.92, highest_prev + 2.5)
    elif urgency >= 4:
        bid = max(DAILY_SALARY * 0.72, highest_prev + 1.5)
    elif urgency >= 2:
        if highest_prev >= DAILY_SALARY * 1.3:
            bid = DAILY_SALARY * 0.52
        else:
            bid = max(DAILY_SALARY * 0.48, avg_prev + 1.0)
    else:
        if tight and highest_prev < DAILY_SALARY * 0.95:
            bid = max(DAILY_SALARY * 0.42, highest_prev + 0.5)
        else:
            bid = DAILY_SALARY * 0.28

    if len(aggressive_bids) >= 2 and urgency <= 2:
        bid = min(bid, DAILY_SALARY * 0.35)

    if supply >= 24 and urgency <= 2:
        bid = min(bid, DAILY_SALARY * 0.22)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    if budget < reserve_floor and urgency <= 3:
        bid = min(bid, DAILY_SALARY * 0.3)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, bid enough to avoid no-water streak
    if not alive_opps:
        cap = min(my_status.get('budget', 0.0), DAILY_SALARY * 0.6)
        return max(0.0, cap)

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass
        elif isinstance(prev, list) and len(prev) > 0:
            # Only immediate trace if list exists
            last = prev[-1]
            if isinstance(last, dict):
                b = last.get('bid', None)
                if b is not None:
                    try:
                        yesterday_bids.append(float(b))
                    except Exception:
                        pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Pressure from supply scarcity: fewer units means higher chance others win water
    # supply is 15-25, water requirement is 9 => scarcity increases when supply closer to 15
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.0
    scarcity = max(0.0, min(1.0, scarcity))

    # Baseline bid: moderate fraction of salary, adjusted by scarcity and my HP
    # If I'm close to death or already on no-water streak, bid aggressively.
    if hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * (0.85 + 0.1 * scarcity)
    else:
        # If yesterday had aggressive bids (>=~100), slightly over-anchor but not maxing out.
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            base = DAILY_SALARY * (0.55 + 0.25 * scarcity)
        else:
            base = DAILY_SALARY * (0.45 + 0.20 * scarcity)

    # Additional reaction: if highest_prev_bid is high, try to beat it by a small margin.
    # Keep this conservative to avoid overspending.
    target = base
    if highest_prev_bid > 0:
        # Beat by 2% of salary or 1.0, whichever is larger, but cap by a reasonable multiple.
        margin = max(1.0, DAILY_SALARY * 0.02)
        target = max(target, min(highest_prev_bid + margin, DAILY_SALARY * 1.05))

    # Final cap by budget
    bid = min(budget, target)
    if bid < 0.0:
        bid = 0.0
    return float(bid)
